const lead = typeof $json.raw_payload === 'string' ? JSON.parse($json.raw_payload) : $json.raw_payload;
const validPhone = typeof lead?.phone === 'string' && /^\+[1-9]\d{7,14}$/.test(lead.phone);
if (!lead || typeof lead.fullName !== 'string' || !validPhone || !['es', 'en'].includes(lead.locale)) {
  throw new Error('Persisted lead payload is invalid');
}
return {
  json: {
    emailKey: $json.email_key,
    metaPayload: {
      messaging_product: 'whatsapp',
      to: lead.phone,
      type: 'template',
      template: {
        name: 'lead_confirmation',
        language: { code: lead.locale === 'es' ? 'es_AR' : 'en_US' },
        components: [{ type: 'body', parameters: [{ type: 'text', text: lead.fullName }] }],
      },
    },
  },
};

const claimed = $('Claim WhatsApp delivery').item.json;
const status = Number($json.statusCode ?? $json.status ?? 0);
const body = $json.body ?? {};
const messageId = typeof body?.messages?.[0]?.id === 'string' ? body.messages[0].id : '';
let nextStatus = 'manual_review';
let failureClass = 'ambiguous';
let failureCode = status ? String(status) : 'transport_or_unknown';
let failureMessage = 'Meta response was missing a verifiable message identifier.';
if (status >= 200 && status < 300 && messageId) {
  nextStatus = 'accepted'; failureClass = ''; failureCode = ''; failureMessage = '';
} else if ([400, 401, 403].includes(status)) {
  nextStatus = 'permanent_failure'; failureClass = 'permanent';
  failureMessage = typeof body?.error?.message === 'string' ? body.error.message : 'Meta rejected the request permanently.';
} else if (status === 429 || status >= 500) {
  nextStatus = 'retryable'; failureClass = 'transient';
  failureMessage = typeof body?.error?.message === 'string' ? body.error.message : 'Meta returned a transient failure.';
}
return { json: { emailKey: claimed.email_key, nextStatus, httpStatus: status, metaMessageId: messageId, failureClass, failureCode, failureMessageBase64: Buffer.from(failureMessage, 'utf8').toString('base64') } };
